if (!api.hasSprite) return;
var T = 2 * Math.PI * api.t;
var sw = api.spriteW, sh = api.spriteH;
var marginX = sw * 0.5 + 2;
var spanX = (api.w - sw - 4) * p.drift;
var cx = api.w * 0.5;
// figure-eight-ish wander: x is one cycle, y is two, so it loops seamlessly
var x = cx + Math.sin(T) * (spanX * 0.5);
var baseY = api.h - 6 - p.turn * 0.5;
var y = baseY + Math.sin(2 * T) * p.turn * 0.5;
// bob: tiny vertical hop tied to the leg cycle
var hop = Math.round(Math.sin(T * 4) * p.bob * 0.5);
// heading: derivative of x tells us which way it is going
var dx = Math.cos(T);
var flip = dx < 0;
// scale the leg cycle with how fast it is actually moving
var legs = Math.floor(api.t * api.frames * 1.5) % 9;
if (legs < 0) legs += 9;
var px = Math.round(x);
var py = Math.round(y) - hop;
if (px < marginX) px = Math.round(marginX);
if (px > api.w - marginX) px = Math.round(api.w - marginX);
// faint drag shadow of kicked sand behind the trailing side
var back = flip ? 1 : -1;
for (var i = 0; i < 5; i++) {
  var g = api.rnd(i * 7 + 3);
  var sx = px + back * (sw * 0.35 + i * 3 + g * 3);
  var sy = py - 1 - Math.round(api.rnd(i * 5 + 11) * 2);
  var fade = (1 - i / 5) * 0.28 * p.intensity;
  api.px(Math.round(sx), sy, '#e7ac6b', fade);
  if (i % 2 === 0) api.px(Math.round(sx) + 1, sy - 1, '#f1e2c4', fade * 0.7);
}
api.sprite(px, py, { flip: flip, frame: legs, alpha: p.intensity });
